// Edge efficiency index — record JAH-GPC-EDGETPU-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"tops": 4, "power_w": 2};
var value = (m.tops*100/m.power_w);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-EDGETPU-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-EDGETPU-000001|' + value.toFixed(2) + ' TOPS-per-watt index');

